settings.liquid:
{%- assign current_variant = product.selected_or_first_available_variant -%}

<div class="custom-atc-wrapper">
  {%- form 'product', product, id: 'custom-atc-form' -%}
    <input type="hidden" name="id" value="{{ current_variant.id }}">

    <div class="atc-flex-row">
      {%- if current_variant.available -%}
        <div class="qty-container-slim">
          <button type="button" class="qty-btn-inv" onclick="this.parentNode.querySelector('input').stepDown()">−</button>
          <input type="number" name="quantity" value="1" min="1" class="qty-input-inv no-arrows">
          <button type="button" class="qty-btn-inv" onclick="this.parentNode.querySelector('input').stepUp()">+</button>
        </div>
      {%- endif -%}

      <button type="submit" name="add" 
        class="main-atc-button {% unless current_variant.available %}btn-out-of-stock{% endunless %}" 
        id="AddToCart-Button"
        data-available="{{ current_variant.available }}">
        <span class="btn-text">
          {%- if current_variant.available -%}
            DODAJ DO KOSZYKA
          {%- else -%}
            POWIADOM O DOSTĘPNOŚCI
          {%- endif -%}
        </span>
      </button>

      <button type="button" class="wishlist-btn-small">
        <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5"><path d="M20.84 4.61a5.5 5.5 0 0 0-7.78 0L12 5.67l-1.06-1.06a5.5 5.5 0 0 0-7.78 7.78l1.06 1.06L12 21.23l7.78-7.78 1.06-1.06a5.5 5.5 0 0 0 0-7.78z"></path></svg>
      </button>
    </div>
  {%- endform -%}
</div>

<div id="notify-modal" class="custom-modal">
  <div class="modal-content">
    <span class="close-modal">&times;</span>
    <h3>Powiadom mnie</h3>
    <p>Zostaw swój e-mail, a damy Ci znać, gdy produkt wróci do sprzedaży.</p>
    {% form 'contact' %}
      {% if form.posted_successfully? %}
        <p class="success-msg">Dziękujemy! Powiadomimy Cię.</p>
      {% endif %}
      <input type="hidden" name="contact[body]" value="Prośba o powiadomienie o dostępności: {{ product.title }} - {{ current_variant.title }}">
      <input type="email" name="contact[email]" placeholder="Twój e-mail" required class="modal-input">
      <button type="submit" class="modal-submit-btn">ZAPISZ MNIE</button>
    {% endform %}
  </div>
</div>

<script>
  document.querySelector('#custom-atc-form').addEventListener('submit', function(e) {
    let btn = document.querySelector('#AddToCart-Button');
    let isAvailable = btn.getAttribute('data-available') === 'true';

    // Jeśli produkt niedostępny - zablokuj wysyłkę do koszyka i pokaż popup
    if (!isAvailable) {
      e.preventDefault();
      document.getElementById('notify-modal').style.display = 'flex';
      return;
    }

    // Jeśli dostępny - standardowa logika dodawania do koszyka (AJAX)
    e.preventDefault();
    let formData = new FormData(this);
    let btnText = btn.querySelector('.btn-text');

    btn.disabled = true; // Blokada przycisku podczas ładowania
    btnText.innerText = 'DODAJE...';

    fetch(window.Shopify.routes.root + 'cart/add.js', {
      method: 'POST',
      body: formData
    })
    .then(response => response.json())
    .then(item => {
      btnText.innerText = 'DODANO! 👍';
      document.dispatchEvent(new CustomEvent('cart:updated', { detail: { cart: item } }));

      const cartDrawer = document.querySelector('cart-drawer') || document.querySelector('#CartDrawer');
      if (cartDrawer && typeof cartDrawer.open === 'function') cartDrawer.open();

      document.documentElement.dispatchEvent(new CustomEvent('cart:refresh', { bubbles: true }));

      setTimeout(() => { 
        btnText.innerText = 'DODAJ DO KOSZYKA'; 
        btn.disabled = false;
      }, 2000);
    })
    .catch((error) => {
      console.error('Error:', error);
      btnText.innerText = 'BŁĄD';
      btn.disabled = false;
    });
  });

  // Obsługa zamykania modala
  document.querySelector('.close-modal').onclick = function() {
    document.getElementById('notify-modal').style.display = 'none';
  }
  window.onclick = function(event) {
    let modal = document.getElementById('notify-modal');
    if (event.target == modal) modal.style.display = 'none';
  }
</script>

<style>
  @import url('https://fonts.googleapis.com/css2?family=Poppins:wght@700&display=swap');

  /* Stylizacja przycisku gdy brak towaru */
  .main-atc-button.btn-out-of-stock {
    background: #a5a8f5; /* Jaśniejszy kolor */
    box-shadow: 0 5px 0 #8084d1;
    cursor: pointer;
  }

  .main-atc-button.btn-out-of-stock:active {
    top: 3px;
    box-shadow: 0 2px 0 #8084d1;
  }

  /* Reszta stylów bez zmian... */
  .custom-atc-wrapper { margin: 15px 0; width: 100%; padding-bottom: 8px; }
  .atc-flex-row { display: flex; gap: 10px; align-items: center; height: 48px; }
  .qty-container-slim { display: flex; align-items: center; background: #ffffff; border: 1px solid #4E54F0; border-radius: 50px; height: 100%; min-width: 85px; }
  .qty-btn-inv { background: transparent; border: none; color: #4E54F0; cursor: pointer; font-size: 16px; width: 28px; display: flex; justify-content: center; }
  .qty-input-inv.no-arrows { background: transparent; border: none; color: #4E54F0; text-align: center; width: 25px; font-family: 'Poppins', sans-serif; font-weight: 700; font-size: 14px; -moz-appearance: textfield; }
  .main-atc-button { position: relative; flex: 1; height: 100%; background: #4E54F0; color: white; border: none; border-radius: 50px; font-family: 'Poppins', sans-serif; font-weight: 700; font-size: 16px; letter-spacing: 0.5px; cursor: pointer; box-shadow: 0 5px 0 #3238b5; transition: all 0.1s ease; top: 0; }
  .wishlist-btn-small { width: 42px; height: 42px; background: transparent; border: 1px solid #e2e2e2; border-radius: 50%; display: flex; align-items: center; justify-content: center; cursor: pointer; color: #888; transition: all 0.2s; flex-shrink: 0; }

  /* Style Modala */
  .custom-modal {
    display: none;
    position: fixed;
    z-index: 9999;
    left: 0; top: 0; width: 100%; height: 100%;
    background-color: rgba(0,0,0,0.5);
    justify-content: center; align-items: center;
  }
  .modal-content {
    background-color: #fff;
    padding: 30px;
    border-radius: 15px;
    width: 90%; max-width: 400px;
    text-align: center;
    position: relative;
    font-family: 'Poppins', sans-serif;
  }
  .close-modal {
    position: absolute; right: 15px; top: 10px;
    font-size: 24px; cursor: pointer;
  }
  .modal-input {
    width: 100%; padding: 12px; margin: 15px 0;
    border: 1px solid #ddd; border-radius: 25px;
    box-sizing: border-box;
  }
  .modal-submit-btn {
    width: 100%; background: #4E54F0; color: #fff;
    border: none; padding: 12px; border-radius: 25px;
    font-weight: 700; cursor: pointer;
  }
  .success-msg { color: green; font-weight: bold; }
</style>
